 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--report',type=Path,default=HERE/'assessment.json');args=ap.parse_args();d=json.loads((HERE/'design.json').read_text());r=json.loads((HERE/'counterbalance.response.json').read_text());receipt=json.loads((HERE/'counterbalance.execution.json').read_text());assert H(HERE/'counterbalance.response.json')==receipt['body_sha256'];assert r['engine']==d['engine']and r['script_sha256']==d['api_adapted_sha256'];assert H(HERE/'native-candidate.lab')==d['native_candidate_sha256']and H(HERE/'api-adapted.lab')==d['api_adapted_sha256'];assert H(HERE/'request.json')==d['request_sha256']
